package lcs

import "testing"

func TestClassicCase(t *testing.T) {
	// ABCBDAB vs BDCABA → LCS length 4 (e.g. BCBA or BDAB)
	if got := LCS("ABCBDAB", "BDCABA"); got != 4 {
		t.Fatalf("expected 4, got %d", got)
	}
}

func TestIdentical(t *testing.T) {
	if got := LCS("hello", "hello"); got != 5 {
		t.Fatalf("expected 5, got %d", got)
	}
}

func TestNoCommon(t *testing.T) {
	if got := LCS("abc", "xyz"); got != 0 {
		t.Fatalf("expected 0, got %d", got)
	}
}

func TestEmpty(t *testing.T) {
	if got := LCS("", "abc"); got != 0 {
		t.Fatalf("expected 0, got %d", got)
	}
	if got := LCS("", ""); got != 0 {
		t.Fatalf("expected 0, got %d", got)
	}
}

func TestSingleChar(t *testing.T) {
	if got := LCS("a", "a"); got != 1 {
		t.Fatalf("expected 1, got %d", got)
	}
	if got := LCS("a", "b"); got != 0 {
		t.Fatalf("expected 0, got %d", got)
	}
}
